import math

def tau(n):
    """Calculates the number of positive divisors of n (tau(n))."""
    if n <= 0:
        return 0
    count = 1
    n = int(n)
    i = 2
    temp = n
    while i * i <= temp:
        exponent = 0
        while temp % i == 0:
            exponent += 1
            temp //= i
        count *= (exponent + 1)
        i += 1
    if temp > 1:
        count *= 2
    return count

